using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows;using System.Windows.Threading;
class AgentCheck {
 static TV tv;static int n;static object Call(string method,params object[] args){return typeof(TV).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(tv,args);}static object Field(string name){return typeof(TV).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(tv);}static void Set(string name,object value){typeof(TV).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(tv,value);}static void Pump(Task task){while(!task.IsCompleted){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);System.Threading.Thread.Sleep(3);}task.GetAwaiter().GetResult();}static void Check(bool ok,string text){if(!ok)throw new Exception(text);n++;Console.WriteLine("PASS "+text);}
 [STAThread]static int Main(string[] args){try{var a=new Application();System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());tv=new TV();Set("serial","192.0.2.1:5555");Pump((Task)Call("Scan"));Check(TV.IsLoopbackAgent("http://127.0.0.1:11434/v1/chat/completions"),"local endpoint accepted");Check(!TV.IsLoopbackAgent("https://cloud.example/v1/chat/completions")&&!TV.IsLoopbackAgent("http://localhost.evil/v1/chat/completions")&&!TV.IsLoopbackAgent("http://key:secret@127.0.0.1/v1/chat/completions"),"external and credential-bearing endpoints rejected");Check(TV.AgentModels("{\"data\":[{\"id\":\"local-model\"}]}","fixture",args[0]+"/v1/chat/completions").Count==1,"model list uses standard compatible protocol");string task=(string)Call("CreateAgentTask");Check(task.Contains("com.android.systemui")&&task.Contains("com.demo.removed")&&task.Contains("path"),"agent handoff contains full scan including removed and system packages");var probe=(Task<List<TV.LocalAgentService>>)typeof(TV).GetMethod("ProbeAgent",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{new Uri(args[0]).Port,"fixture"});Pump(probe);Check(probe.Result.Count==1,"automatic local discovery reads model endpoint");Pump((Task)Call("AnalyzeAgent",new TV.LocalAgentService{Name="fixture",Model="local-model",Url=args[0]+"/v1/chat/completions"}));var rows=(List<Package>)Field("packages");Check(rows.First(p=>p.Id=="com.android.systemui").Risk=="疑似系统组件","agent low advice cannot override system classification");Check(rows.First(p=>p.Id=="com.demo.video").Risk=="推荐卸载","third party recommendation classified");Check(rows.All(p=>p.AiOpinion!=null&&p.AiOpinion.Contains("AI 意见")),"AI opinions shown for every returned package");Pump((Task)Call("ApplyChange","uninstall","com.android.systemui"));Pump((Task)Call("ApplyChange","uninstall","com.vendor.tvhome"));Check(File.ReadAllText("mock-commands.log").Contains("pm uninstall --user 0 com.android.systemui")&&File.ReadAllText("mock-commands.log").Contains("pm uninstall --user 0 com.vendor.tvhome"),"core and desktop use ordinary current-user uninstall");bool rejected=false;try{Pump((Task)Call("ApplyChange","uninstall","com.bad;id"));}catch{rejected=true;}Check(rejected,"invalid package rejected before command");Set("scannedFor","other-tv");rejected=false;try{Pump((Task)Call("ApplyChange","uninstall","com.android.systemui"));}catch{rejected=true;}Check(rejected,"scan cannot cross device");Check(!File.ReadAllText("mock-commands.log").Contains("adb root")&&!File.ReadAllText("mock-commands.log").Contains("su -c"),"no implicit root acquisition");Console.WriteLine(n+" agent checks passed; simulated ADB only");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
